function validate([head]) {
  if (!Array.isArray(head) || head.length < 1 || head.length > 100000) return 'The list holds 1 to 10^5 nodes.';
  if (head.some(v => !Number.isInteger(v) || v < 1 || v > 100000)) return 'Each node value is an integer from 1 to 10^5.';
  return null;
}

