  const count = new Map();
  for (let node = head; node !== null; node = node.next) {
    count.set(node.val, (count.get(node.val) || 0) + 1);
  }

  const dummy = new ListNode(0);
  let tail = dummy;
  for (const frequency of count.values()) {
    tail.next = new ListNode(frequency);
    tail = tail.next;
  }
  return dummy.next;
}

