function frequenciesOfElements(head) {
  const values = [];
  for (let p = head; p; p = p.next) values.push(p.val);
  values.sort((a, b) => a - b);
  const runs = [];
  let start = 0;
  for (let i = 1; i <= values.length; i++) {
    if (i === values.length || values[i] !== values[start]) { runs.push(i - start); start = i; }
  }
  let result = null;
  for (let k = runs.length - 1; k >= 0; k--) result = new ListNode(runs[k], result);
  return result;
}

