function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'large') {
    const span = [5, 300, 100000][int(0, 2)];
    return [Array.from({ length: 2000 }, () => int(1, span))];
  }
  const span = [1, 3, 10][int(0, 2)];
  return [Array.from({ length: int(1, 9) }, () => int(1, span))];
}
